package com.printflow.files;
import java.util.*;import java.awt.*;import java.awt.image.BufferedImage;import java.io.*;
/** Authored fictional examples only; never customer portfolio files. */
public final class ArtworkSamples {
 private static final Map<String,String> NAMES=Map.of("WEDDING_CARDS","Wedding invitation","HOTEL_PRINT","Hotel menu","OFFSET_GLOSS","Promotional flyer","BROCHURES","Product brochure","CARDS","Business card","BOOKS","Book cover","PACKAGING","Packaging sleeve","CUSTOM","Custom print layout");
 public static java.util.List<Map<String,String>> list(String product){return NAMES.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->Map.of("code",e.getKey(),"title",e.getValue(),"category",e.getKey(),"description","Fictional example layout — select and describe your changes.")).toList();}
 public static byte[] png(String code)throws IOException{if(!NAMES.containsKey(code))throw new NoSuchElementException();var image=new BufferedImage(600,800,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(248,245,235));g.fillRect(0,0,600,800);g.setColor(new Color(25,70,74));g.fillRect(28,28,544,130);g.setColor(Color.WHITE);g.setFont(new Font("SansSerif",Font.BOLD,28));g.drawString(NAMES.get(code),52,90);g.setFont(new Font("SansSerif",Font.PLAIN,16));g.drawString("J.D.Printex • Sample layout",52,125);g.setColor(new Color(55,108,102));g.setStroke(new BasicStroke(3));g.drawRect(50,190,500,380);g.setFont(new Font("Serif",Font.ITALIC,30));g.drawString("Your story goes here",98,310);g.setFont(new Font("SansSerif",Font.PLAIN,17));g.drawString("Add your names, message and colours",98,365);g.drawString("Mark places to ask the designer for changes",70,425);g.setColor(new Color(25,70,74));g.drawString("FICTIONAL EXAMPLE • NOT PRINT-READY",75,650);g.drawString("No customer artwork or personal information",70,686);g.drawString(code.replace('_',' '),70,735);}finally{g.dispose();}var out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);return out.toByteArray();}
}
